function createReactiveSystem() {
  const deps = new Map()
  let active = null
  const stack = []

  function track(key) {
    if (!active) return
    let bucket = deps.get(key)
    if (!bucket) {
      bucket = new Set()
      deps.set(key, bucket)
    }
    bucket.add(active)
  }

  function trigger(key) {
    const bucket = deps.get(key)
    if (!bucket) return 0
    const snapshot = Array.from(bucket)
    for (const fn of snapshot) fn()
    return snapshot.length
  }

  function reactive(target) {
    return new Proxy(target, {
      get(obj, key) {
        track(key)
        return obj[key]
      },
      set(obj, key, value) {
        if (Object.is(obj[key], value)) return true
        obj[key] = value
        trigger(key)
        return true
      }
    })
  }

  function effect(fn) {
    const run = () => {
      stack.push(active)
      active = fn
      try {
        return fn()
      } finally {
        active = stack.pop()
      }
    }
    run()
    return run
  }

  return { reactive, effect, trigger }
}

