function createScheduler() {
  const queue = []
  const runs = []
  let flushing = false
  let pending = false

  function queueJob(job) {
    const found = queue.find((item) => item.id === job.id)
    if (found) {
      found.run = job.run
      return
    }
    queue.push(job)
    if (!flushing) queue.sort((a, b) => a.id - b.id)
    if (!pending) {
      pending = true
      Promise.resolve().then(() => {
        pending = false
        flushJobs()
      })
    }
  }

  function flushJobs() {
    if (flushing) return []
    flushing = true
    const ran = []
    try {
      while (queue.length) {
        queue.sort((a, b) => a.id - b.id)
        const job = queue.shift()
        if (ran.length >= 100) throw new Error('调度器递归触发超过上限 100 次')
        job.run()
        ran.push(job.id)
        runs.push(job.id)
      }
    } finally {
      flushing = false
      queue.length = 0
    }
    return ran
  }

  function nextTick(fn) {
    return Promise.resolve().then(fn || function () {})
  }

  return {
    queueJob,
    flushJobs,
    nextTick,
    runs,
    size: () => queue.length
  }
}

